CREATE DATABASE IF NOT EXISTS eskewela;
USE eskewela;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('STUDENT','FACULTY','ADMIN','SUPER_ADMIN') NOT NULL DEFAULT 'STUDENT',status ENUM('ACTIVE','DISABLED') NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS students (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,student_no VARCHAR(50) NOT NULL UNIQUE,first_name VARCHAR(100) NOT NULL,middle_name VARCHAR(100),last_name VARCHAR(100) NOT NULL,dob DATE,phone VARCHAR(40),address TEXT,program VARCHAR(150),year_level VARCHAR(30),section VARCHAR(50),academic_status VARCHAR(50) DEFAULT 'Regular',photo_url VARCHAR(500),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS faculty (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,full_name VARCHAR(200) NOT NULL,department VARCHAR(150),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS terms (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,is_current BOOLEAN DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS subjects (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(30) NOT NULL UNIQUE,title VARCHAR(200) NOT NULL,units DECIMAL(4,1) NOT NULL);
CREATE TABLE IF NOT EXISTS sections (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,program VARCHAR(150),year_level VARCHAR(30));
CREATE TABLE IF NOT EXISTS schedules (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,subject_id BIGINT UNSIGNED NOT NULL,section_id BIGINT UNSIGNED,faculty_id BIGINT UNSIGNED,day_of_week ENUM('MON','TUE','WED','THU','FRI','SAT') NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,room VARCHAR(80),FOREIGN KEY(subject_id) REFERENCES subjects(id),FOREIGN KEY(section_id) REFERENCES sections(id),FOREIGN KEY(faculty_id) REFERENCES faculty(id));
CREATE TABLE IF NOT EXISTS enrollments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,term_id BIGINT UNSIGNED NOT NULL,status ENUM('PENDING','APPROVED','REJECTED','ENROLLED') DEFAULT 'PENDING',submitted_at TIMESTAMP NULL,reviewed_at TIMESTAMP NULL,remarks TEXT,FOREIGN KEY(student_id) REFERENCES students(id),FOREIGN KEY(term_id) REFERENCES terms(id));
CREATE TABLE IF NOT EXISTS enrollment_subjects (enrollment_id BIGINT UNSIGNED NOT NULL,schedule_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(enrollment_id,schedule_id),FOREIGN KEY(enrollment_id) REFERENCES enrollments(id) ON DELETE CASCADE,FOREIGN KEY(schedule_id) REFERENCES schedules(id));
CREATE TABLE IF NOT EXISTS grades (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,subject_id BIGINT UNSIGNED NOT NULL,term_id BIGINT UNSIGNED NOT NULL,grade DECIMAL(5,2),remarks VARCHAR(100),FOREIGN KEY(student_id) REFERENCES students(id),FOREIGN KEY(subject_id) REFERENCES subjects(id),FOREIGN KEY(term_id) REFERENCES terms(id));
CREATE TABLE IF NOT EXISTS billing (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,term_id BIGINT UNSIGNED NOT NULL,total_tuition DECIMAL(12,2) DEFAULT 0,discounts DECIMAL(12,2) DEFAULT 0,other_fees DECIMAL(12,2) DEFAULT 0,due_date DATE,FOREIGN KEY(student_id) REFERENCES students(id));
CREATE TABLE IF NOT EXISTS payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,billing_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(12,2) NOT NULL,status ENUM('PENDING','PAID','FAILED','CANCELLED') DEFAULT 'PENDING',reference VARCHAR(100) UNIQUE,paid_at TIMESTAMP NULL,FOREIGN KEY(billing_id) REFERENCES billing(id));
CREATE TABLE IF NOT EXISTS document_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,request_no VARCHAR(40) NOT NULL UNIQUE,document_type VARCHAR(120) NOT NULL,status ENUM('PENDING','PROCESSING','READY','RELEASED','CANCELLED') DEFAULT 'PENDING',requested_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,release_date DATE,remarks TEXT,FOREIGN KEY(student_id) REFERENCES students(id));
CREATE TABLE IF NOT EXISTS clearance (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,department VARCHAR(120) NOT NULL,status ENUM('PENDING','CLEARED','HAS_CONCERN') DEFAULT 'PENDING',checked_at DATE,remarks TEXT,FOREIGN KEY(student_id) REFERENCES students(id));
CREATE TABLE IF NOT EXISTS announcements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,description TEXT NOT NULL,author_id BIGINT UNSIGNED NOT NULL,category VARCHAR(80) DEFAULT 'University Update',published_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(author_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(200) NOT NULL,message TEXT NOT NULL,is_read BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS digital_ids (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL UNIQUE,qr_token CHAR(64) NOT NULL UNIQUE,status ENUM('ACTIVE','SUSPENDED','EXPIRED') DEFAULT 'ACTIVE',issued_at DATE NOT NULL,FOREIGN KEY(student_id) REFERENCES students(id));
CREATE TABLE IF NOT EXISTS id_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,reason VARCHAR(255) NOT NULL,status ENUM('PENDING','PROCESSING','READY','RELEASED','CANCELLED') DEFAULT 'PENDING',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id));
CREATE TABLE IF NOT EXISTS sessions (token_hash CHAR(64) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,expires_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,action VARCHAR(120) NOT NULL,entity VARCHAR(80),entity_id BIGINT UNSIGNED,ip VARCHAR(64),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
